// Usage:
//   import { shareText } from '../zzz/share'
//   const outcome = await shareText({ message: 'Regarde mon score !', url: 'https://…' })
//   // 'shared' = sheet completed · 'copied' = no sheet, text copied (show a
//   // DIFFERENT feedback) · 'dismissed' = user closed it · 'failed'
import { Platform, Share } from 'react-native'
import * as Clipboard from 'expo-clipboard'

export type ShareOutcome = 'shared' | 'copied' | 'dismissed' | 'failed'

export async function shareText(input: { message: string; url?: string; title?: string }): Promise<ShareOutcome> {
  const message = [input.message, input.url].filter(Boolean).join('\n')
  try {
    if (Platform.OS === 'web') {
      const nav = typeof navigator !== 'undefined' ? (navigator as any) : null
      if (nav?.share) {
        try { await nav.share({ title: input.title, text: input.message, url: input.url }); return 'shared' }
        catch { return 'dismissed' }
      }
      await Clipboard.setStringAsync(message)
      return 'copied'
    }
    const result = await Share.share({ message, title: input.title }, { dialogTitle: input.title })
    return result.action === Share.dismissedAction ? 'dismissed' : 'shared'
  } catch {
    try { await Clipboard.setStringAsync(message); return 'copied' } catch { return 'failed' }
  }
}
